script:
$wrapper = @"
param([Parameter(ValueFromRemainingArguments=`$true)][string[]]`$UserArgs)
`$originalPwd = (Get-Location).Path
`$resolvedArgs = @()
`$nextIsOutput = `$false
foreach (`$arg in `$UserArgs) {
  if (`$nextIsOutput) {
    if ([System.IO.Path]::IsPathRooted(`$arg)) {
      `$resolvedArgs += `$arg
    } else {
      `$resolvedArgs += (Join-Path `$originalPwd `$arg)
    }
    `$nextIsOutput = `$false
  } elseif (`$arg -eq '-o') {
    `$resolvedArgs += '-o'
    `$nextIsOutput = `$true
  } elseif (Test-Path `$arg) {
    `$resolvedArgs += (Resolve-Path `$arg).Path
  } else {
    `$resolvedArgs += `$arg
  }
}
Set-Location "$libexec"
& bb 'fill_docx.bb' @resolvedArgs
"@
